 3	// [ai, aj[
 4	function sum(a: array<int>, i: int, j: int) : int
 5	  requires 0 <= i <= j <= a.Length
 6	  reads a
 7	  decreases j
 8	{
 9	  if i == j then 0
10	  else a[j-1] + sum(a, i, j-1)
11	}
12	
13	// 1 b)
14	method query(a: array<int>, i: int, j: int) returns (res : int)
15	  requires 0 <= i <= j <= a.Length
16	  ensures res == sum(a, i, j)
17	{
18	  res := 0;
19	  var ind := j-1;
20	
21	  while ind >= i
22	    invariant res == sum(a, i, j) - sum(a, i, ind+1)
23	    decreases ind
24	  {
25	    res := res + a[ind];
26	    ind := ind - 1;
27	  }
28	}
29	
30	// 1 c)
31	// a -> [1, 10, 3, −4, 5]
32	// c -> [0, 1, 11, 14, 10, 15]
33	method queryFast(a: array<int>, c: array<int>, i: int, j: int) returns (r: int)
34	  requires 0 <= i <= j <= a.Length
35	  requires is_prefix_sum_for(a,c)
36	  ensures r == sum(a, i, j)
37	{
38	  var k := i;
39	  proof(a, 0, j, k);
40	  r := c[j] - c[i];
41	}
42	
43	predicate is_prefix_sum_for (a: array<int>, c: array<int>)
44	  reads c, a
45	{
46	  a.Length + 1 == c.Length && forall i: int :: 0 <= i <= a.Length ==> c[i] == sum(a, 0, i)
47	}
48	
49	lemma proof(a: array<int>, i: int, j: int, k:int)
50	  requires 0 <= i <= k <= j <= a.Length
51	  ensures sum(a, i, k) + sum(a, k, j) == sum(a, i, j)
52	
